// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

/// @notice Minimal ERC20 used for LP tokens.
/// @dev Includes EIP-2612 permit (gasless approvals) to ease router UX.
contract PurDexERC20 {
    string public constant name = "PurDex LP";
    string public constant symbol = "PURDEX-LP";
    uint8 public constant decimals = 18;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value);

    // --- EIP-2612 permit ---
    bytes32 public immutable DOMAIN_SEPARATOR;
    // keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)")
    bytes32 public constant PERMIT_TYPEHASH =
        0x6e71edae12b1b97f4d1f60370fef10105fa2faae0126114a169c64845d6126c9;
    mapping(address => uint256) public nonces;

    constructor() {
        uint256 chainId;
        assembly {
            chainId := chainid()
        }
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256(bytes(name)),
                keccak256(bytes("1")),
                chainId,
                address(this)
            )
        );
    }

    function _mint(address to, uint256 value) internal {
        totalSupply += value;
        balanceOf[to] += value;
        emit Transfer(address(0), to, value);
    }

    function _burn(address from, uint256 value) internal {
        balanceOf[from] -= value;
        totalSupply -= value;
        emit Transfer(from, address(0), value);
    }

    function _approve(address owner, address spender, uint256 value) private {
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        _approve(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - value;
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function permit(
        address owner,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        require(deadline >= block.timestamp, "PERMIT_DEADLINE_EXPIRED");

        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))
            )
        );

        address recovered = ecrecover(digest, v, r, s);
        require(recovered != address(0) && recovered == owner, "INVALID_PERMIT_SIGNATURE");
        _approve(owner, spender, value);
    }
}

contracts/dex/PurDexFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";

import "./PurDexPair.sol";

/// @notice Factory that creates PurDexPair contracts.
/// @dev
///  - This factory is deployed behind a UUPS proxy.
///  - Pairs are deployed behind an OZ BeaconProxy, so you can upgrade all pairs later by upgrading the beacon.
///  - Optionally integrates with a KYC manager to auto-register newly created pairs.
contract PurDexFactory is Initializable, OwnableUpgradeable, UUPSUpgradeable {
    error PurDexFactory__IdenticalAddresses();
    error PurDexFactory__ZeroAddress();
    error PurDexFactory__PairExists();

    event PairCreated(address indexed token0, address indexed token1, address pair, uint256);
    event KycManagerUpdated(address indexed kycManager);
    event PairBeaconUpdated(address indexed pairBeacon);
    event FeeToUpdated(address indexed feeTo);

    address public feeTo;
    address public feeToSetter;

    // Optional hook: called after creating a pair so the pair can be KYC-verified in your IdentityRegistry.
    address public kycManager;

    // Beacon used for all pairs.
    address public pairBeacon;

    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @dev UUPS initializer
    function initialize(address _feeToSetter, address _kycManager, address _pairBeacon) external initializer {
        __Ownable_init();
        __UUPSUpgradeable_init();

        if (_feeToSetter == address(0)) revert PurDexFactory__ZeroAddress();
        feeToSetter = _feeToSetter;
        kycManager = _kycManager;
        pairBeacon = _pairBeacon;
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    function setFeeTo(address _feeTo) external {
        require(msg.sender == feeToSetter, "FORBIDDEN");
        feeTo = _feeTo;
        emit FeeToUpdated(_feeTo);
    }

    function setFeeToSetter(address _feeToSetter) external {
        require(msg.sender == feeToSetter, "FORBIDDEN");
        feeToSetter = _feeToSetter;
    }

    function setKycManager(address _kycManager) external {
        require(msg.sender == feeToSetter, "FORBIDDEN");
        kycManager = _kycManager;
        emit KycManagerUpdated(_kycManager);
    }

    function setPairBeacon(address _pairBeacon) external {
        require(msg.sender == feeToSetter, "FORBIDDEN");
        pairBeacon = _pairBeacon;
        emit PairBeaconUpdated(_pairBeacon);
    }

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        if (tokenA == tokenB) revert PurDexFactory__IdenticalAddresses();
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert PurDexFactory__ZeroAddress();
        if (getPair[token0][token1] != address(0)) revert PurDexFactory__PairExists();
        if (pairBeacon == address(0)) revert PurDexFactory__ZeroAddress();

        // Beacon proxy init: initialize(factory, token0, token1)
        bytes memory initData = abi.encodeWithSelector(PurDexPair.initialize.selector, address(this), token0, token1);
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));
        pair = address(new BeaconProxy{salt: salt}(pairBeacon, initData));

        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair; // populate mapping in the reverse direction
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);

        // Auto-register pair in IdentityRegistry via your KYC manager (optional)
        if (kycManager != address(0)) {
            // best-effort; if the manager reverts, pair still exists but must be registered manually.
            (bool ok, ) = kycManager.call(abi.encodeWithSignature("registerDexContract(address)", pair));
            ok; // ignore
        }
    }
}

contracts/dex/PurDexPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";

import "./libraries/Math.sol";
import "./libraries/TransferHelper.sol";
import "./interfaces/IPurDexFactory.sol";

/// @notice Constant-product AMM pair (similar shape to UniswapV2Pair).
/// @dev
///  - Deployed behind an OZ BeaconProxy (one proxy per pair).
///  - Upgrading the beacon upgrades the logic for all pairs.
///  - This contract MUST be initialized via initialize().
contract PurDexPair is Initializable, ERC20PermitUpgradeable {
    using TransferHelper for address;

    error PurDexPair__Forbidden();
    error PurDexPair__Locked();
    error PurDexPair__InsufficientLiquidityMinted();
    error PurDexPair__InsufficientLiquidityBurned();
    error PurDexPair__InsufficientOutputAmount();
    error PurDexPair__InsufficientInputAmount();
    error PurDexPair__InvalidTo();
    error PurDexPair__KInvariant();

    uint256 public constant MINIMUM_LIQUIDITY = 1_000;
    address private constant LOCK_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    address public factory;
    address public token0;
    address public token1;

    uint112 private reserve0; // uses single storage slot, accessible via getReserves
    uint112 private reserve1; // uses single storage slot, accessible via getReserves
    uint32 private blockTimestampLast;

    uint256 public price0CumulativeLast;
    uint256 public price1CumulativeLast;
    uint256 public kLast; // reserve0 * reserve1, as of immediately after the most recent liquidity event

    uint256 private unlocked;
    modifier lock() {
        if (unlocked != 1) revert PurDexPair__Locked();
        unlocked = 0;
        _;
        unlocked = 1;
    }

    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(
        address indexed sender,
        uint256 amount0In,
        uint256 amount1In,
        uint256 amount0Out,
        uint256 amount1Out,
        address indexed to
    );
    event Sync(uint112 reserve0, uint112 reserve1);

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @dev Initializer (called once by the factory).
    function initialize(address _factory, address _token0, address _token1) external initializer {
        if (_factory == address(0) || _token0 == address(0) || _token1 == address(0)) revert PurDexPair__Forbidden();
        factory = _factory;
        token0 = _token0;
        token1 = _token1;

        __ERC20_init("PurDex LP", "PURDEX-LP");
        __ERC20Permit_init("PurDex LP");

        unlocked = 1;
    }

    function getReserves()
        public
        view
        returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast)
    {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    // --- internal helpers ---
    function _safeBalance(address token) private view returns (uint256) {
        (bool ok, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        require(ok && data.length >= 32, "BALANCEOF_FAILED");
        return abi.decode(data, (uint256));
    }

    function _update(uint256 balance0, uint256 balance1, uint112 _reserve0, uint112 _reserve1) private {
        require(balance0 <= type(uint112).max && balance1 <= type(uint112).max, "OVERFLOW");

        uint32 blockTimestamp = uint32(block.timestamp % 2**32);
        uint32 timeElapsed = blockTimestamp - blockTimestampLast;

        if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
            // price accumulators (fixed point, Q112.112). We keep it for TWAP integrations.
            price0CumulativeLast += (uint256(_reserve1) << 112) / uint256(_reserve0) * timeElapsed;
            price1CumulativeLast += (uint256(_reserve0) << 112) / uint256(_reserve1) * timeElapsed;
        }

        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = blockTimestamp;
        emit Sync(reserve0, reserve1);
    }

    function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns (bool feeOn) {
        address feeTo = IPurDexFactory(factory).feeTo();
        feeOn = feeTo != address(0);
        uint256 _kLast = kLast;

        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = Math.sqrt(uint256(_reserve0) * uint256(_reserve1));
                uint256 rootKLast = Math.sqrt(_kLast);
                if (rootK > rootKLast) {
                    // 1/6th of growth in sqrt(k)
                    uint256 numerator = totalSupply() * (rootK - rootKLast);
                    uint256 denominator = (rootK * 5) + rootKLast;
                    uint256 liquidity = numerator / denominator;
                    if (liquidity > 0) _mint(feeTo, liquidity);
                }
            }
        } else if (_kLast != 0) {
            kLast = 0;
        }
    }

    // --- external AMM actions ---
    function mint(address to) external lock returns (uint256 liquidity) {
        (uint112 _reserve0, uint112 _reserve1, ) = getReserves();
        uint256 balance0 = _safeBalance(token0);
        uint256 balance1 = _safeBalance(token1);
        uint256 amount0 = balance0 - _reserve0;
        uint256 amount1 = balance1 - _reserve1;

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        if (_totalSupply == 0) {
            liquidity = Math.sqrt(amount0 * amount1) - MINIMUM_LIQUIDITY;
            // OZ ERC20 forbids minting to address(0). We lock the minimum liquidity forever at a dead address.
            _mint(LOCK_ADDRESS, MINIMUM_LIQUIDITY);
        } else {
            liquidity = Math.min((amount0 * _totalSupply) / _reserve0, (amount1 * _totalSupply) / _reserve1);
        }

        if (liquidity == 0) revert PurDexPair__InsufficientLiquidityMinted();
        _mint(to, liquidity);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * uint256(reserve1);
        emit Mint(msg.sender, amount0, amount1);
    }

    function burn(address to) external lock returns (uint256 amount0, uint256 amount1) {
        (uint112 _reserve0, uint112 _reserve1, ) = getReserves();

        uint256 balance0 = _safeBalance(token0);
        uint256 balance1 = _safeBalance(token1);
        uint256 liquidity = balanceOf(address(this));

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        amount0 = (liquidity * balance0) / _totalSupply;
        amount1 = (liquidity * balance1) / _totalSupply;
        if (amount0 == 0 || amount1 == 0) revert PurDexPair__InsufficientLiquidityBurned();

        _burn(address(this), liquidity);
        token0.safeTransfer(to, amount0);
        token1.safeTransfer(to, amount1);

        balance0 = _safeBalance(token0);
        balance1 = _safeBalance(token1);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * uint256(reserve1);
        emit Burn(msg.sender, amount0, amount1, to);
    }

    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata) external lock {
        if (amount0Out == 0 && amount1Out == 0) revert PurDexPair__InsufficientOutputAmount();
        (uint112 _reserve0, uint112 _reserve1, ) = getReserves();
        require(amount0Out < _reserve0 && amount1Out < _reserve1, "INSUFFICIENT_LIQUIDITY");
        if (to == token0 || to == token1) revert PurDexPair__InvalidTo();

        if (amount0Out > 0) token0.safeTransfer(to, amount0Out);
        if (amount1Out > 0) token1.safeTransfer(to, amount1Out);

        uint256 balance0 = _safeBalance(token0);
        uint256 balance1 = _safeBalance(token1);

        uint256 amount0In = balance0 > (_reserve0 - amount0Out) ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > (_reserve1 - amount1Out) ? balance1 - (_reserve1 - amount1Out) : 0;
        if (amount0In == 0 && amount1In == 0) revert PurDexPair__InsufficientInputAmount();

        // Adjusted balances (0.30% fee)
        uint256 balance0Adjusted = (balance0 * 1000) - (amount0In * 3);
        uint256 balance1Adjusted = (balance1 * 1000) - (amount1In * 3);
        if (balance0Adjusted * balance1Adjusted < uint256(_reserve0) * uint256(_reserve1) * 1_000_000) {
            revert PurDexPair__KInvariant();
        }

        _update(balance0, balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    function skim(address to) external lock {
        token0.safeTransfer(to, _safeBalance(token0) - reserve0);
        token1.safeTransfer(to, _safeBalance(token1) - reserve1);
    }

    function sync() external lock {
        _update(_safeBalance(token0), _safeBalance(token1), reserve0, reserve1);
    }
}

contracts/dex/PurDexRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "../IIdentityRegistry.sol";

import "./interfaces/IPurDexFactory.sol";
import "./interfaces/IPurDexPair.sol";
import "./interfaces/IWETH.sol";
import "./libraries/PurDexLibrary.sol";
import "./libraries/TransferHelper.sol";

/// @notice Router for the PurDex AMM.
/// @dev Adds a KYC gate for paths involving PUR (ERC3643-like token with IdentityRegistry).
contract PurDexRouter is Initializable, ReentrancyGuardUpgradeable, OwnableUpgradeable, UUPSUpgradeable {
    using TransferHelper for address;

    error Router__Expired();
    error Router__InvalidPath();
    error Router__KycRequired();
    error Router__InsufficientA();
    error Router__InsufficientB();
    error Router__InsufficientOutput();

    address public factory;
    address public WETH;
    address public PUR;
    IIdentityRegistry public identityRegistry;

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    modifier ensure(uint256 deadline) {
        if (deadline < block.timestamp) revert Router__Expired();
        _;
    }

    function initialize(address _factory, address _weth, address _pur, address _identityRegistry) external initializer {
        __ReentrancyGuard_init();
        __Ownable_init();
        __UUPSUpgradeable_init();

        require(_factory != address(0) && _weth != address(0) && _pur != address(0) && _identityRegistry != address(0), "ZERO");
        factory = _factory;
        WETH = _weth;
        PUR = _pur;
        identityRegistry = IIdentityRegistry(_identityRegistry);
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    receive() external payable {
        require(msg.sender == WETH, "ONLY_WETH");
    }
    function version() external pure returns (string memory) { return "v2"; }
    // --- KYC helpers ---
    function _pathTouchesPUR(address[] memory path) internal view returns (bool) {
        address pur = PUR;
        for (uint256 i = 0; i < path.length; i++) {
            if (path[i] == pur) return true;
        }
        return false;
    }

    function _requireVerified(address who) internal view {
        if (!identityRegistry.isVerified(who)) revert Router__KycRequired();
    }

    function _requireKycIfNeeded(address[] memory path, address to) internal view {
        if (_pathTouchesPUR(path)) {
            _requireVerified(msg.sender);
            _requireVerified(to);
        }
    }

    // --- liquidity ---
    function _addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin
    ) internal returns (uint256 amountA, uint256 amountB) {
        // create pair if needed
        if (IPurDexFactory(factory).getPair(tokenA, tokenB) == address(0)) {
            IPurDexFactory(factory).createPair(tokenA, tokenB);
        }

        (uint256 reserveA, uint256 reserveB) = PurDexLibrary.getReserves(factory, tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = PurDexLibrary.quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                if (amountBOptimal < amountBMin) revert Router__InsufficientB();
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = PurDexLibrary.quote(amountBDesired, reserveB, reserveA);
                if (amountAOptimal < amountAMin) revert Router__InsufficientA();
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external nonReentrant ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        address[] memory path = new address[](2);
        path[0] = tokenA;
        path[1] = tokenB;
        _requireKycIfNeeded(path, to);

        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = IPurDexFactory(factory).getPair(tokenA, tokenB);

        tokenA.safeTransferFrom(msg.sender, pair, amountA);
        tokenB.safeTransferFrom(msg.sender, pair, amountB);
        liquidity = IPurDexPair(pair).mint(to);
    }

    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable nonReentrant ensure(deadline) returns (uint256 amountToken, uint256 amountETH, uint256 liquidity) {
        address[] memory path = new address[](2);
        path[0] = token;
        path[1] = WETH;
        _requireKycIfNeeded(path, to);

        (amountToken, amountETH) = _addLiquidity(
            token,
            WETH,
            amountTokenDesired,
            msg.value,
            amountTokenMin,
            amountETHMin
        );

        address pair = IPurDexFactory(factory).getPair(token, WETH);
        token.safeTransferFrom(msg.sender, pair, amountToken);

        IWETH(WETH).deposit{value: amountETH}();
        WETH.safeTransfer(pair, amountETH);
        liquidity = IPurDexPair(pair).mint(to);

        // refund dust ETH
        if (msg.value > amountETH) {
            TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH);
        }
    }

    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) public nonReentrant ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address[] memory path = new address[](2);
        path[0] = tokenA;
        path[1] = tokenB;
        _requireKycIfNeeded(path, to);

        address pair = IPurDexFactory(factory).getPair(tokenA, tokenB);
        require(pair != address(0), "PAIR_NOT_FOUND");

        pair.safeTransferFrom(msg.sender, pair, liquidity);
        (uint256 amount0, uint256 amount1) = IPurDexPair(pair).burn(to);
        (address token0, ) = PurDexLibrary.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        if (amountA < amountAMin) revert Router__InsufficientA();
        if (amountB < amountBMin) revert Router__InsufficientB();
    }

    function removeLiquidityETH(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external nonReentrant ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(token, WETH, liquidity, amountTokenMin, amountETHMin, address(this), deadline);

        token.safeTransfer(to, amountToken);
        IWETH(WETH).withdraw(amountETH);
        TransferHelper.safeTransferETH(to, amountETH);
    }

    // --- swaps ---
    function _swap(uint256[] memory amounts, address[] memory path, address _to) internal {
        for (uint256 i = 0; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0, ) = PurDexLibrary.sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0
                ? (uint256(0), amountOut)
                : (amountOut, uint256(0));

            address to = i < path.length - 2
                ? IPurDexFactory(factory).getPair(output, path[i + 2])
                : _to;

            IPurDexPair(IPurDexFactory(factory).getPair(input, output)).swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external nonReentrant ensure(deadline) returns (uint256[] memory amounts) {
        if (path.length < 2) revert Router__InvalidPath();
        address[] memory mpath = path;
        _requireKycIfNeeded(mpath, to);

        amounts = PurDexLibrary.getAmountsOut(factory, amountIn, mpath);
        if (amounts[amounts.length - 1] < amountOutMin) revert Router__InsufficientOutput();

        address pair = IPurDexFactory(factory).getPair(mpath[0], mpath[1]);
        mpath[0].safeTransferFrom(msg.sender, pair, amounts[0]);
        _swap(amounts, mpath, to);
    }

    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable nonReentrant ensure(deadline) returns (uint256[] memory amounts) {
        if (path.length < 2) revert Router__InvalidPath();
        require(path[0] == WETH, "PATH_MUST_START_WETH");
        address[] memory mpath = path;
        _requireKycIfNeeded(mpath, to);

        amounts = PurDexLibrary.getAmountsOut(factory, msg.value, mpath);
        if (amounts[amounts.length - 1] < amountOutMin) revert Router__InsufficientOutput();

        IWETH(WETH).deposit{value: amounts[0]}();
        address pair = IPurDexFactory(factory).getPair(mpath[0], mpath[1]);
        WETH.safeTransfer(pair, amounts[0]);
        _swap(amounts, mpath, to);
    }

    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external nonReentrant ensure(deadline) returns (uint256[] memory amounts) {
        if (path.length < 2) revert Router__InvalidPath();
        require(path[path.length - 1] == WETH, "PATH_MUST_END_WETH");
        address[] memory mpath = path;
        _requireKycIfNeeded(mpath, to);

        amounts = PurDexLibrary.getAmountsOut(factory, amountIn, mpath);
        if (amounts[amounts.length - 1] < amountOutMin) revert Router__InsufficientOutput();

        address pair = IPurDexFactory(factory).getPair(mpath[0], mpath[1]);
        mpath[0].safeTransferFrom(msg.sender, pair, amounts[0]);
        _swap(amounts, mpath, address(this));
        uint256 amountOut = amounts[amounts.length - 1];
        IWETH(WETH).withdraw(amountOut);
        TransferHelper.safeTransferETH(to, amountOut);
    }

    // --- convenience swaps for ETH <-> PUR ---
    /// @notice Swap native ETH directly to PUR (internally wraps to WETH).
    /// @dev Equivalent to swapExactETHForTokens with path [WETH, PUR].
    function swapExactETHForPUR(
        uint256 amountOutMin,
        address to,
        uint256 deadline
    ) external payable nonReentrant ensure(deadline) returns (uint256[] memory amounts) {
        address[] memory path = new address[](2);
        path[0] = WETH;
        path[1] = PUR;
        _requireKycIfNeeded(path, to);

        amounts = PurDexLibrary.getAmountsOut(factory, msg.value, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert Router__InsufficientOutput();

        IWETH(WETH).deposit{value: amounts[0]}();
        address pair = IPurDexFactory(factory).getPair(path[0], path[1]);
        WETH.safeTransfer(pair, amounts[0]);
        _swap(amounts, path, to);
    }

    /// @notice Swap PUR directly to native ETH (internally unwraps WETH).
    /// @dev Equivalent to swapExactTokensForETH with path [PUR, WETH].
    function swapExactPURForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address to,
        uint256 deadline
    ) external nonReentrant ensure(deadline) returns (uint256[] memory amounts) {
        address[] memory path = new address[](2);
        path[0] = PUR;
        path[1] = WETH;
        _requireKycIfNeeded(path, to);

        amounts = PurDexLibrary.getAmountsOut(factory, amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert Router__InsufficientOutput();

        address pair = IPurDexFactory(factory).getPair(path[0], path[1]);
        path[0].safeTransferFrom(msg.sender, pair, amounts[0]);
        _swap(amounts, path, address(this));
        uint256 amountOut = amounts[amounts.length - 1];
        IWETH(WETH).withdraw(amountOut);
        TransferHelper.safeTransferETH(to, amountOut);
    }

    // --- pure/view helpers for frontends ---
    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB) external pure returns (uint256 amountB) {
        return PurDexLibrary.quote(amountA, reserveA, reserveB);
    }

    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) external pure returns (uint256 amountOut) {
        return PurDexLibrary.getAmountOut(amountIn, reserveIn, reserveOut);
    }

    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut) external pure returns (uint256 amountIn) {
        return PurDexLibrary.getAmountIn(amountOut, reserveIn, reserveOut);
    }

    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts) {
        return PurDexLibrary.getAmountsOut(factory, amountIn, path);
    }

    function getAmountsIn(uint256 amountOut, address[] calldata path) external view returns (uint256[] memory amounts) {
        return PurDexLibrary.getAmountsIn(factory, amountOut, path);
    }
}

