contracts/lending/PurDexLendingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "../IIdentityRegistry.sol";
import "../interfaces/IPuriCoin.sol";
import "../dex/interfaces/IWETH.sol";
import "../dex/libraries/TransferHelper.sol";
import "./PurDexOracleRouter.sol";

/// @title PurDexLendingPool
/// @notice A minimal money-market for PUR, inspired by Aave/Compound.
/// @dev
///  - Suppliers deposit PUR to earn interest.
///  - Borrowers lock ETH (WETH) as collateral and borrow PUR.
///  - Interest accrues to borrowers over time; suppliers earn from borrower interest.
///
/// Parameters (per your spec):
///  - Variable interest with base=2% and slope=20% (utilization based)
///  - LTV=50%, liquidation threshold=60%, liquidation bonus=5%
contract PurDexLendingPool is Initializable, OwnableUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
    using TransferHelper for address;

    // --- constants ---
    uint256 public constant WAD = 1e18;
    uint256 public constant BPS = 10_000;
    uint256 public constant SECONDS_PER_YEAR = 31_536_000;

    // --- external deps ---
    IPuriCoin public pur;
    IWETH public weth;
    IIdentityRegistry public identityRegistry;
    PurDexOracleRouter public oracle;

    // --- risk params ---
    uint256 public ltvBps; // 50%
    uint256 public liquidationThresholdBps; // 60%
    uint256 public liquidationBonusBps; // +5%

    // --- interest params ---
    uint256 public baseRatePerYear; // 2% APR (WAD)
    uint256 public slopePerYear; // +20% APR at 100% util (WAD)
    uint256 public reserveFactorBps; // % of borrower interest to protocol reserves

    // --- supply accounting (shares) ---
    uint256 public totalSupplyShares;
    mapping(address => uint256) public supplyShares;

    // --- borrow accounting (Compound-like index) ---
    struct BorrowSnapshot {
        uint256 principal;
        uint256 interestIndex;
    }
    mapping(address => BorrowSnapshot) public accountBorrows;

    uint256 public totalBorrows;
    uint256 public totalReserves;
    uint256 public borrowIndex;
    uint256 public lastAccrual;

    // --- collateral ---
    mapping(address => uint256) public collateralWeth;

    // --- events ---
    event OracleUpdated(address oracle);
    event RiskParamsUpdated(uint256 ltvBps, uint256 liquidationThresholdBps, uint256 liquidationBonusBps);
    event InterestParamsUpdated(uint256 baseRatePerYear, uint256 slopePerYear, uint256 reserveFactorBps);
    event Accrued(uint256 interestAccumulated, uint256 newBorrowIndex, uint256 newTotalBorrows, uint256 newTotalReserves);

    event Supplied(address indexed user, uint256 amount, uint256 shares);
    event Withdrawn(address indexed user, uint256 amount, uint256 shares);
    event CollateralDeposited(address indexed user, uint256 wethAmount);
    event CollateralWithdrawn(address indexed user, uint256 wethAmount);
    event Borrowed(address indexed user, uint256 amount, uint256 newDebt);
    event Repaid(address indexed payer, address indexed borrower, uint256 amount, uint256 remainingDebt);
    event Liquidated(address indexed liquidator, address indexed borrower, uint256 repaidPur, uint256 seizedWeth);

    error LP__KycRequired();
    error LP__ZeroAmount();
    error LP__InsufficientLiquidity();
    error LP__HealthFactorTooLow();
    error LP__NotLiquidatable();

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _pur, address _weth, address _identityRegistry, address _oracle) external initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        require(_pur != address(0) && _weth != address(0) && _identityRegistry != address(0) && _oracle != address(0), "ZERO");
        pur = IPuriCoin(_pur);
        weth = IWETH(_weth);
        identityRegistry = IIdentityRegistry(_identityRegistry);
        oracle = PurDexOracleRouter(_oracle);

        // defaults per your requested config
        ltvBps = 5_000;
        liquidationThresholdBps = 6_000;
        liquidationBonusBps = 500;
        baseRatePerYear = 2e16; // 2%
        slopePerYear = 2e17; // 20%
        reserveFactorBps = 1_000; // 10%

        borrowIndex = WAD;
        lastAccrual = block.timestamp;
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    receive() external payable {
        // only allow receiving ETH from WETH withdraw
        require(msg.sender == address(weth), "ONLY_WETH");
    }

    // --- admin ---
    function setOracle(address _oracle) external onlyOwner {
        require(_oracle != address(0), "ZERO");
        oracle = PurDexOracleRouter(_oracle);
        emit OracleUpdated(_oracle);
    }

    function setRiskParams(uint256 _ltvBps, uint256 _liqThresholdBps, uint256 _liqBonusBps) external onlyOwner {
        require(_ltvBps <= _liqThresholdBps && _liqThresholdBps <= BPS, "BAD_PARAMS");
        ltvBps = _ltvBps;
        liquidationThresholdBps = _liqThresholdBps;
        liquidationBonusBps = _liqBonusBps;
        emit RiskParamsUpdated(_ltvBps, _liqThresholdBps, _liqBonusBps);
    }

    function setInterestParams(uint256 _baseRatePerYear, uint256 _slopePerYear, uint256 _reserveFactorBps) external onlyOwner {
        require(_reserveFactorBps <= BPS, "BAD_PARAMS");
        baseRatePerYear = _baseRatePerYear;
        slopePerYear = _slopePerYear;
        reserveFactorBps = _reserveFactorBps;
        emit InterestParamsUpdated(_baseRatePerYear, _slopePerYear, _reserveFactorBps);
    }

    /// @notice Withdraw protocol reserves (earned from reserveFactor).
    function withdrawReserves(address to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "ZERO");
        accrueInterest();
        require(amount <= totalReserves, "TOO_MUCH");
        totalReserves -= amount;
        address(pur).safeTransfer(to, amount);
    }

    // --- KYC ---
    function _requireVerified(address who) internal view {
        if (!identityRegistry.isVerified(who)) revert LP__KycRequired();
    }

    // --- rates ---
    function utilization() public view returns (uint256 utilWad) {
        uint256 cash = IERC20(address(pur)).balanceOf(address(this));
        if (totalBorrows == 0) return 0;
        return (totalBorrows * WAD) / (cash + totalBorrows);
    }

    function borrowRatePerSecond() public view returns (uint256 ratePerSecondWad) {
        uint256 util = utilization();
        uint256 ratePerYear = baseRatePerYear + ((slopePerYear * util) / WAD);
        return ratePerYear / SECONDS_PER_YEAR;
    }

    // --- interest accrual ---
    function accrueInterest() public {
        uint256 ts = block.timestamp;
        uint256 dt = ts - lastAccrual;
        if (dt == 0) return;

        lastAccrual = ts;
        if (totalBorrows == 0) return;

        uint256 rate = borrowRatePerSecond();
        uint256 interestFactor = rate * dt; // WAD
        uint256 interestAccumulated = (totalBorrows * interestFactor) / WAD;
        if (interestAccumulated == 0) return;

        uint256 reservesAdded = (interestAccumulated * reserveFactorBps) / BPS;
        totalReserves += reservesAdded;
        totalBorrows += interestAccumulated;

        // update borrow index
        borrowIndex += (borrowIndex * interestFactor) / WAD;

        emit Accrued(interestAccumulated, borrowIndex, totalBorrows, totalReserves);
    }

    // --- views ---
    function totalAssets() public view returns (uint256 assets) {
        uint256 cash = IERC20(address(pur)).balanceOf(address(this));
        assets = cash + totalBorrows;
        if (assets >= totalReserves) assets -= totalReserves;
        else assets = 0;
    }

    function exchangeRate() public view returns (uint256) {
        if (totalSupplyShares == 0) return WAD;
        return (totalAssets() * WAD) / totalSupplyShares;
    }

    function supplyBalanceUnderlying(address user) external view returns (uint256) {
        if (totalSupplyShares == 0) return 0;
        return (supplyShares[user] * totalAssets()) / totalSupplyShares;
    }

    function borrowBalanceCurrent(address borrower) public view returns (uint256) {
        BorrowSnapshot memory bs = accountBorrows[borrower];
        if (bs.principal == 0) return 0;
        return (bs.principal * borrowIndex) / bs.interestIndex;
    }

    function accountLiquidity(address user)
        public
        view
        returns (uint256 collateralUsd, uint256 debtUsd, uint256 maxBorrowUsd, bool liquidatable)
    {
        (uint256 ethPrice, ) = oracle.ethUsdPrice();
        (uint256 purPrice, ) = oracle.purUsdPrice();

        collateralUsd = (collateralWeth[user] * ethPrice) / WAD;
        uint256 debtPur = borrowBalanceCurrent(user);
        debtUsd = (debtPur * purPrice) / WAD;
        maxBorrowUsd = (collateralUsd * ltvBps) / BPS;
        uint256 liqThresholdUsd = (collateralUsd * liquidationThresholdBps) / BPS;
        liquidatable = debtUsd > liqThresholdUsd;
    }

    // --- supply ---
    function supply(uint256 amount) external nonReentrant {
        _requireVerified(msg.sender);
        if (amount == 0) revert LP__ZeroAmount();

        accrueInterest();

        uint256 assets = totalAssets();
        uint256 shares;
        if (totalSupplyShares == 0) {
            shares = amount;
        } else {
            shares = (amount * totalSupplyShares) / assets;
        }

        require(shares > 0, "SHARES_ZERO");

        totalSupplyShares += shares;
        supplyShares[msg.sender] += shares;

        address(pur).safeTransferFrom(msg.sender, address(this), amount);
        emit Supplied(msg.sender, amount, shares);
    }

    function withdraw(uint256 shares) external nonReentrant {
        _requireVerified(msg.sender);
        if (shares == 0) revert LP__ZeroAmount();
        require(shares <= supplyShares[msg.sender], "NOT_ENOUGH_SHARES");

        accrueInterest();
        uint256 amount = (shares * totalAssets()) / totalSupplyShares;

        uint256 cash = IERC20(address(pur)).balanceOf(address(this));
        if (amount > cash) revert LP__InsufficientLiquidity();

        supplyShares[msg.sender] -= shares;
        totalSupplyShares -= shares;

        address(pur).safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount, shares);
    }

    // --- collateral ---
    function depositCollateralETH() external payable nonReentrant {
        _requireVerified(msg.sender);
        if (msg.value == 0) revert LP__ZeroAmount();
        weth.deposit{value: msg.value}();
        collateralWeth[msg.sender] += msg.value;
        emit CollateralDeposited(msg.sender, msg.value);
    }

    function withdrawCollateralETH(uint256 wethAmount) external nonReentrant {
        _requireVerified(msg.sender);
        if (wethAmount == 0) revert LP__ZeroAmount();
        require(wethAmount <= collateralWeth[msg.sender], "NOT_ENOUGH_COLLATERAL");

        accrueInterest();
        collateralWeth[msg.sender] -= wethAmount;
        if (!_isHealthy(msg.sender)) {
            collateralWeth[msg.sender] += wethAmount;
            revert LP__HealthFactorTooLow();
        }

        weth.withdraw(wethAmount);
        TransferHelper.safeTransferETH(msg.sender, wethAmount);
        emit CollateralWithdrawn(msg.sender, wethAmount);
    }

    // --- borrow/repay ---
    function borrow(uint256 amount) external nonReentrant {
        _requireVerified(msg.sender);
        if (amount == 0) revert LP__ZeroAmount();
        accrueInterest();

        uint256 cash = IERC20(address(pur)).balanceOf(address(this));
        if (amount > cash) revert LP__InsufficientLiquidity();

        if (!_canBorrow(msg.sender, amount)) revert LP__HealthFactorTooLow();

        uint256 currentDebt = borrowBalanceCurrent(msg.sender);
        uint256 newPrincipal = currentDebt + amount;
        accountBorrows[msg.sender] = BorrowSnapshot({principal: newPrincipal, interestIndex: borrowIndex});
        totalBorrows += amount;

        address(pur).safeTransfer(msg.sender, amount);
        emit Borrowed(msg.sender, amount, newPrincipal);
    }

    function repay(uint256 amount) external nonReentrant {
        accrueInterest();
        _repayFrom(msg.sender, msg.sender, amount);
    }

    function repayOnBehalf(address borrower, uint256 amount) external nonReentrant {
        accrueInterest();
        _repayFrom(msg.sender, borrower, amount);
    }

    function _repayFrom(address payer, address borrower, uint256 amount) internal {
        _requireVerified(payer);
        _requireVerified(borrower);
        if (amount == 0) revert LP__ZeroAmount();
        uint256 debt = borrowBalanceCurrent(borrower);
        uint256 repayAmount = amount > debt ? debt : amount;
        require(repayAmount > 0, "NO_DEBT");

        uint256 newPrincipal = debt - repayAmount;
        accountBorrows[borrower] = BorrowSnapshot({principal: newPrincipal, interestIndex: borrowIndex});
        totalBorrows -= repayAmount;

        address(pur).safeTransferFrom(payer, address(this), repayAmount);
        emit Repaid(payer, borrower, repayAmount, newPrincipal);
    }

    // --- liquidation ---
    function liquidate(address borrower, uint256 repayAmount) external nonReentrant {
        _requireVerified(msg.sender);
        _requireVerified(borrower);
        if (repayAmount == 0) revert LP__ZeroAmount();

        accrueInterest();
        (, , , bool liquidatable) = accountLiquidity(borrower);
        if (!liquidatable) revert LP__NotLiquidatable();

        uint256 debt = borrowBalanceCurrent(borrower);
        uint256 actualRepay = repayAmount > debt ? debt : repayAmount;
        require(actualRepay > 0, "NO_DEBT");

        (uint256 ethPrice, ) = oracle.ethUsdPrice();
        (uint256 purPrice, ) = oracle.purUsdPrice();

        uint256 repayUsd = (actualRepay * purPrice) / WAD;
        uint256 seizeUsd = (repayUsd * (BPS + liquidationBonusBps)) / BPS;
        uint256 seizeWethAmount = (seizeUsd * WAD) / ethPrice;

        uint256 borrowerColl = collateralWeth[borrower];
        if (seizeWethAmount > borrowerColl) {
            seizeWethAmount = borrowerColl;
            uint256 seizeUsdCapped = (seizeWethAmount * ethPrice) / WAD;
            uint256 repayUsdCapped = (seizeUsdCapped * BPS) / (BPS + liquidationBonusBps);
            actualRepay = (repayUsdCapped * WAD) / purPrice;
        }

        _repayFrom(msg.sender, borrower, actualRepay);

        collateralWeth[borrower] -= seizeWethAmount;
        require(weth.transfer(msg.sender, seizeWethAmount), "WETH_TRANSFER_FAIL");
        emit Liquidated(msg.sender, borrower, actualRepay, seizeWethAmount);
    }

    // --- internal health checks ---
    function _canBorrow(address borrower, uint256 additionalPur) internal view returns (bool) {
        (uint256 collateralUsd, uint256 debtUsd, uint256 maxBorrowUsd, ) = accountLiquidity(borrower);
        (uint256 purPrice, ) = oracle.purUsdPrice();
        uint256 addUsd = (additionalPur * purPrice) / WAD;
        if (collateralUsd == 0) return false;
        return debtUsd + addUsd <= maxBorrowUsd;
    }

    function _isHealthy(address borrower) internal view returns (bool) {
        (uint256 collateralUsd, uint256 debtUsd, uint256 maxBorrowUsd, ) = accountLiquidity(borrower);
        if (debtUsd == 0) return true;
        if (collateralUsd == 0) return false;
        return debtUsd <= maxBorrowUsd;
    }
}

contracts/lending/PurDexOracleRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

import "./interfaces/INAVOracle.sol";

/// @title PurDexOracleRouter
/// @notice Normalizes oracle prices into a single 1e18 fixed-point format.
/// @dev
///  - ETH/USD comes from Chainlink AggregatorV3Interface.
///  - PUR/USD comes from your NAVOracle (manual or Chainlink-backed).
///  - Each price can fall back to a manual value if a feed is not set or if you prefer.
contract PurDexOracleRouter is Initializable, OwnableUpgradeable, UUPSUpgradeable {
    error Oracle__BadAnswer();
    error Oracle__Stale();

    AggregatorV3Interface public ethUsdFeed; // optional
    INAVOracle public purUsdOracle; // optional

    uint256 public manualEthUsdPrice1e18;
    uint256 public manualPurUsdPrice1e18;
    bool public useManualEth;
    bool public useManualPur;

    /// @notice If > 0, oracle answers older than this are considered stale.
    uint256 public maxAge;

    event EthFeedUpdated(address feed);
    event PurOracleUpdated(address oracle);
    event ManualEthUpdated(uint256 price1e18, bool enabled);
    event ManualPurUpdated(uint256 price1e18, bool enabled);
    event MaxAgeUpdated(uint256 maxAge);

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _ethUsdFeed, address _purUsdOracle) external initializer {
        __Ownable_init();
        __UUPSUpgradeable_init();

        if (_ethUsdFeed != address(0)) {
            ethUsdFeed = AggregatorV3Interface(_ethUsdFeed);
        }
        if (_purUsdOracle != address(0)) {
            purUsdOracle = INAVOracle(_purUsdOracle);
        }
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    function setMaxAge(uint256 _maxAge) external onlyOwner {
        maxAge = _maxAge;
        emit MaxAgeUpdated(_maxAge);
    }

    function setEthUsdFeed(address feed) external onlyOwner {
        ethUsdFeed = AggregatorV3Interface(feed);
        useManualEth = false;
        emit EthFeedUpdated(feed);
    }

    function setPurUsdOracle(address oracle) external onlyOwner {
        purUsdOracle = INAVOracle(oracle);
        useManualPur = false;
        emit PurOracleUpdated(oracle);
    }

    function setManualEthUsdPrice(uint256 price1e18, bool enabled) external onlyOwner {
        manualEthUsdPrice1e18 = price1e18;
        useManualEth = enabled;
        emit ManualEthUpdated(price1e18, enabled);
    }

    function setManualPurUsdPrice(uint256 price1e18, bool enabled) external onlyOwner {
        manualPurUsdPrice1e18 = price1e18;
        useManualPur = enabled;
        emit ManualPurUpdated(price1e18, enabled);
    }

    /// @notice ETH/USD price in 1e18.
    function ethUsdPrice() external view returns (uint256 price1e18, uint256 updatedAt) {
        return _ethUsdPrice();
    }

    /// @notice PUR/USD price in 1e18.
    function purUsdPrice() external view returns (uint256 price1e18, uint256 updatedAt) {
        return _purUsdPrice();
    }

    function _ethUsdPrice() internal view returns (uint256 price1e18, uint256 updatedAt) {
        if (useManualEth || address(ethUsdFeed) == address(0)) {
            return (manualEthUsdPrice1e18, block.timestamp);
        }
        (, int256 answer, , uint256 updated, ) = ethUsdFeed.latestRoundData();
        if (answer <= 0) revert Oracle__BadAnswer();
        updatedAt = updated;
        if (maxAge > 0 && updatedAt + maxAge < block.timestamp) revert Oracle__Stale();
        uint8 d = ethUsdFeed.decimals();
        price1e18 = _scaleTo1e18(uint256(answer), d);
    }

    function _purUsdPrice() internal view returns (uint256 price1e18, uint256 updatedAt) {
        if (useManualPur || address(purUsdOracle) == address(0)) {
            return (manualPurUsdPrice1e18, block.timestamp);
        }
        (uint256 nav, uint8 d, uint256 updated, ) = purUsdOracle.latestNAV();
        if (nav == 0) revert Oracle__BadAnswer();
        updatedAt = updated;
        if (maxAge > 0 && updatedAt + maxAge < block.timestamp) revert Oracle__Stale();
        price1e18 = _scaleTo1e18(nav, d);
    }

    function _scaleTo1e18(uint256 value, uint8 decimals_) internal pure returns (uint256) {
        if (decimals_ == 18) return value;
        if (decimals_ < 18) return value * (10 ** (18 - decimals_));
        return value / (10 ** (decimals_ - 18));
    }
}

contracts/NAVOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

/**
 * @title NAVOracle
 * @notice NAV oracle with optional Chainlink feed and manual fallback.
 * @dev If chainlinkFeed is set, {latestNAV} returns feed data; otherwise it returns manual values.
 */



contract NAVOracle is Ownable {
    /// @notice Optional Chainlink AggregatorV3 feed. Set to address(0) to disable.
    AggregatorV3Interface public chainlinkFeed;

    /// @notice Manual NAV value used when no Chainlink feed is configured.
    uint256 public manualNav;

    /// @notice Decimals for the manual NAV value.
    uint8 public manualDecimals;

    /// @notice Timestamp when manual NAV was last updated.
    uint256 public manualUpdatedAt;

    /// @notice Emitted when NAV is updated (manual update always emits; Chainlink returns are indicated in latestNAV).
    event NAVUpdated(uint256 nav, uint8 decimals, bool fromChainlink);

    /**
     * @param feed Chainlink AggregatorV3 address (optional; can be address(0)).
     */
    constructor(address feed) {
        if (feed != address(0)) {
            chainlinkFeed = AggregatorV3Interface(feed);
        }
    }

    /**
     * @notice Update the Chainlink feed address.
     * @param feed AggregatorV3 address (use address(0) to disable).
     * @dev Only callable by the owner.
     */
    function setChainlinkFeed(address feed) external onlyOwner {
        chainlinkFeed = AggregatorV3Interface(feed);
    }

    /**
     * @notice Set NAV manually (fallback when Chainlink is disabled).
     * @param nav_ NAV value.
     * @param decimals_ NAV decimals.
     * @dev Only callable by the owner.
     */
    function setManualNAV(uint256 nav_, uint8 decimals_) external onlyOwner {
        manualNav = nav_;
        manualDecimals = decimals_;
        manualUpdatedAt = block.timestamp;
        emit NAVUpdated(nav_, decimals_, false);
    }

    /**
     * @notice Return the latest NAV data.
     * @return nav NAV value.
     * @return decimals_ NAV decimals.
     * @return updatedAt Timestamp for the NAV value.
     * @return chainlink True if Chainlink feed was used, false if manual fallback.
     */
    function latestNAV()
        external
        view
        returns (uint256 nav, uint8 decimals_, uint256 updatedAt, bool chainlink)
    {
        if (address(chainlinkFeed) != address(0)) {
            (, int256 answer,, uint256 updated,) = chainlinkFeed.latestRoundData();
            require(answer > 0, "Invalid feed");
            decimals_ = chainlinkFeed.decimals();
            return (uint256(answer), decimals_, updated, true);
        }

        return (manualNav, manualDecimals, manualUpdatedAt, false);
    }
}

contracts/ProofRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ProofRegistry
 * @notice Registry for associating off-chain documents/proofs with an asset identifier.
 * @dev Stores an array of Document structs per assetId. Only owner can add in this version.
 */


contract ProofRegistry is Ownable {

    /// @notice Document record stored for an asset.

    struct Document {

        /// @notice Document type label (e.g., 'KYC', 'Deed', 'Audit').
        string docType;

        /// @notice URI to the document (IPFS or HTTPS).
        string uri;

        /// @notice Hash of the document content for integrity verification.
        bytes32 hash;

        /// @notice Timestamp when the record was created.
        uint256 createdAt;
    }

    /// @dev Internal mapping of documents per assetId.
    mapping(bytes32 => Document[]) private _docs;

    /// @notice Emitted when a new document is added for an asset.
    event DocumentAdded(bytes32 indexed assetId, uint256 index, string docType, string uri);

    /**
     * @notice Add a new document record for an asset.
     * @param assetId Asset identifier (e.g., a hash of an off-chain ID).
     * @param docType Document type label.
     * @param uri Document URI (IPFS/HTTPS).
     * @param hash Document content hash.
     * @dev Only callable by the owner.
     */
    function addDocument(
        bytes32 assetId,
        string calldata docType,
        string calldata uri,
        bytes32 hash
    ) external onlyOwner {
        _docs[assetId].push(
            Document({
                docType: docType,
                uri: uri,
                hash: hash,
                createdAt: block.timestamp
            })
        );
        emit DocumentAdded(assetId, _docs[assetId].length - 1, docType, uri);
    }

    /**
     * @notice Get all documents for an asset.
     * @param assetId Asset identifier.
     */
    function getDocuments(bytes32 assetId) external view returns (Document[] memory) {
        return _docs[assetId];
    }
}

contracts/rewards/PurDexStakingRewards.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "../IIdentityRegistry.sol";
import "../interfaces/IPuriCoin.sol";
import "../dex/libraries/TransferHelper.sol";

/// @title PurDexStakingRewards
/// @notice Stake an LP token (or any ERC20) and earn PUR rewards.
/// @dev
///  - Rewards can be pre-funded OR minted (if this contract is set as an agent on PuriCoin).
///  - Because PUR transfers are KYC-gated, this contract requires `IdentityRegistry.isVerified(user)`.
contract PurDexStakingRewards is Initializable, OwnableUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
    using TransferHelper for address;

    error SR__KycRequired();
    error SR__ZeroAmount();

    IERC20 public stakingToken;
    IPuriCoin public rewardsToken;
    IIdentityRegistry public identityRegistry;

    uint256 public duration;
    uint256 public periodFinish;
    uint256 public rewardRate; // rewards per second
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;

    mapping(address => uint256) public userRewardPerTokenPaid;
    mapping(address => uint256) public rewards;

    uint256 private _totalSupply;
    mapping(address => uint256) private _balances;

    event RewardAdded(uint256 reward);
    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, uint256 reward);
    event DurationUpdated(uint256 newDuration);

    /// @dev Prevent the implementation contract from being initialized directly.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _stakingToken,
        address _rewardsToken,
        address _identityRegistry,
        uint256 _duration
    ) external initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        require(_stakingToken != address(0) && _rewardsToken != address(0) && _identityRegistry != address(0), "ZERO");
        stakingToken = IERC20(_stakingToken);
        rewardsToken = IPuriCoin(_rewardsToken);
        identityRegistry = IIdentityRegistry(_identityRegistry);
        duration = _duration;
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            rewards[account] = earned(account);
            userRewardPerTokenPaid[account] = rewardPerTokenStored;
        }
        _;
    }

    function _requireVerified(address who) internal view {
        if (!identityRegistry.isVerified(who)) revert SR__KycRequired();
    }

    function totalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function lastTimeRewardApplicable() public view returns (uint256) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish;
    }

    function rewardPerToken() public view returns (uint256) {
        if (_totalSupply == 0) {
            return rewardPerTokenStored;
        }
        return rewardPerTokenStored +
            (((lastTimeRewardApplicable() - lastUpdateTime) * rewardRate * 1e18) / _totalSupply);
    }

    function earned(address account) public view returns (uint256) {
        return ((_balances[account] * (rewardPerToken() - userRewardPerTokenPaid[account])) / 1e18) + rewards[account];
    }

    function stake(uint256 amount) external nonReentrant updateReward(msg.sender) {
        _requireVerified(msg.sender);
        if (amount == 0) revert SR__ZeroAmount();

        _totalSupply += amount;
        _balances[msg.sender] += amount;
        address(stakingToken).safeTransferFrom(msg.sender, address(this), amount);
        emit Staked(msg.sender, amount);
    }

    function withdraw(uint256 amount) public nonReentrant updateReward(msg.sender) {
        _requireVerified(msg.sender);
        if (amount == 0) revert SR__ZeroAmount();
        _totalSupply -= amount;
        _balances[msg.sender] -= amount;
        address(stakingToken).safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    function getReward() public nonReentrant updateReward(msg.sender) {
        _requireVerified(msg.sender);
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            rewards[msg.sender] = 0;
            address(rewardsToken).safeTransfer(msg.sender, reward);
            emit RewardPaid(msg.sender, reward);
        }
    }

    function exit() external {
        withdraw(_balances[msg.sender]);
        getReward();
    }

    /// @notice Start a new reward period. Can be funded by minting or by pre-funding this contract.
    /// @dev If you set this contract as an agent on PuriCoin, it can mint rewards into itself.
    function notifyRewardAmount(uint256 reward) external onlyOwner updateReward(address(0)) {
        if (reward == 0) revert SR__ZeroAmount();

        // Mint rewards to this contract if possible (requires agent role on PuriCoin).
        // If you don't want minting, comment this line out and instead transfer PUR to this contract first.
        try rewardsToken.mint(address(this), reward) {} catch {
            // ignore; assumes contract already has the reward balance
        }

        if (block.timestamp >= periodFinish) {
            rewardRate = reward / duration;
        } else {
            uint256 remaining = periodFinish - block.timestamp;
            uint256 leftover = remaining * rewardRate;
            rewardRate = (reward + leftover) / duration;
        }

        // Do not promise more rewards than the contract can pay.
        uint256 balance = IERC20(address(rewardsToken)).balanceOf(address(this));
        require(rewardRate <= balance / duration, "REWARD_TOO_HIGH");

        lastUpdateTime = block.timestamp;
        periodFinish = block.timestamp + duration;
        emit RewardAdded(reward);
    }

    function setDuration(uint256 _duration) external onlyOwner {
        require(block.timestamp > periodFinish, "ONGOING_PERIOD");
        duration = _duration;
        emit DurationUpdated(_duration);
    }
}

